mapper.select:
select
A.id as id,
A.sd_id as sdId,
A.site as site,
A."date" as "date",
A."time" as "time",
A.water_depth as waterDepth,
A.longitude as longitude,
A.latitude as latitude,
A.spm as spm,
A.pim as pim,
A.pom as pom,
A.pim_per as pimPer,
A.pom_per as pomPer,
A.chla as chla,
A.sst as sst,
A.salinity as salinity,
A.ag as ag,
A.s as s,
A.cdom as cdom,
A.tsm as tsm,
A.ssh as ssh,
A.wind as wind,
A."current" as "current",
A.device_model as deviceModel
FROM
sd_observe_data A



        AND A.water_depth >= #{dto.waterDepthStart}


        AND A.water_depth <= #{dto.waterDepthEnd}



        AND A.sd_id=#{dto.sdId}




        AND A.spm >= #{dto.spmStart}


        AND A.spm <= #{dto.spmEnd}




        AND A.pim >= #{dto.pimStart}


        AND A.pim <= #{dto.pimEnd}




        AND A.pom >= #{dto.pomStart}


        AND A.pom <= #{dto.pomEnd}




        AND A.pim_per >= #{dto.pimPerStart}


        AND A.pim_per <= #{dto.pimPerEnd}




        AND A.pom_per >= #{dto.pomPerStart}


        AND A.pom_per <= #{dto.pomPerEnd}




        AND A.chla >= #{dto.chlaStart}


        AND A.chla <= #{dto.chlaEnd}




        AND A.sst >= #{dto.sstStart}


        AND A.sst <= #{dto.sstEnd}




        AND A.salinity >= #{dto.salinityStart}


        AND A.salinity <= #{dto.salinityEnd}




        AND A.tsm >= #{dto.tsmStart}


        AND A.tsm <= #{dto.tsmEnd}




        AND A.ssh >= #{dto.sshStart}


        AND A.ssh <= #{dto.sshEnd}




        AND A.wind >= #{dto.windStart}


        AND A.wind <= #{dto.windEnd}




        AND A."current" >= #{dto.currentStart}


        AND A."current" <= #{dto.currentEnd}




        AND A.ag >= #{dto.agStart}


        AND A.ag <= #{dto.agEnd}




        AND A.s >= #{dto.sStart}


        AND A.s <= #{dto.sEnd}




        AND A.cdom >= #{dto.cdomStart}


        AND A.cdom <= #{dto.cdomEnd}




        AND A.device_mode in

            #{item}






            AND A."date" between #{dto.startDate} and #{dto.endDate}


            AND EXTRACT(MONTH FROM A.date) IN

                #{month}



            AND EXTRACT(YEAR FROM A.date) IN

                #{year}







            AND ST_Intersects(A.geom,ST_GeomFromText(#{dto.wkt},4326))


            AND A.geom IS NOT NULL
            AND ST_Intersects(ST_Transform(A.geom,3857),st_buffer(ST_Transform(ST_GeomFromText(#{dto.wkt},4326),3857),#{dto.radius}))


            AND A.site IN

                #{site}
